sys_variable_value.value:
(function execute(inputs, outputs) {

    var utils = new InsuranceUtils(inputs.patient_id, inputs.policy_id, inputs.provider);

    var insuranceDetails = utils.getInsuranceDetailsByPatientID();
    outputs.insurance_details = (typeof insuranceDetails === 'object') ? JSON.stringify(insuranceDetails) : insuranceDetails;

    var isActive = utils.isPolicyActive();
    outputs.policy_active = isActive;

    var policyDetails = utils.getInsurancePolicyById();
    outputs.policy_details = (typeof policyDetails === 'object') ? JSON.stringify(policyDetails) : policyDetails;

    var policiesByProvider = utils.getInsurancePoliciesByProvider();
    outputs.policies_by_provider = JSON.stringify(policiesByProvider);

})(inputs, outputs);

